using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Informs TDLib that the chat is closed by the user. Many useful activities depend on the chat being opened or closed
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> CloseChatAsync(long chatId = default)
    {

           using var activity =  StartCallActivity("CloseChatAsync", typeof(CloseChat).FullName ?? "CloseChatAsync");

           try
           {
             return client.CloseChatAsync(chatId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd